import Cleanup
import DictationCore
import Foundation

@main struct Probe {
    static func main() throws {
        let transcript = StableTranscript("alpha beta gamma")
        print("spans", transcript.spans)
        let validator = CleanupEditPlanValidator(configuration: .init(maximumInputTokens: 2048))
        let cap = CleanupEdit(startSpan: 0, endSpan: 1, replacement: "Alpha", category: .capitalization)
        let dot = CleanupEdit(startSpan: 0, endSpan: 0, replacement: ".", category: .punctuation)
        let context = TargetContext(applicationIdentifier: "test", applicationCategory: .textEditor, textBeforeCursor: "", textAfterCursor: "", selectedText: nil)
        let decoded = try JSONDecoder().decode(CleanupEditPlan.self, from: Data(#"{"v":1,"e":[{"s":0,"e":1,"r":"Alpha","c":"capitalization"},{"s":0,"e":1,"r":"Alpha","c":"capitalization"}]}"#.utf8))
        print("decoded",decoded, "categoryEqual", decoded.edits[0].category == .capitalization)
        for (name, edits) in [("single-cap",[cap]),("overlap-cap",[cap,cap]),("single-dot",[dot]),("overlap-dot",[dot,dot]),("decoded",decoded.edits)] {
            do {
                _ = try validator.validate(.init(edits: edits), transcript: transcript, reservedEdits: [], targetContext: context, personalVocabulary: .init(entries: []))
                print(name,"accepted")
            } catch let error as CleanupEditValidationError {
                print(name,"error",String(describing:error),"overlap?",error == .unorderedOrOverlapping,"unsafe?",error == .unsafeCategory)
            } catch { print(name,"unexpected",error) }
        }
    }
}
